// @ts-check
import { defineConfig } from "astro/config";
import starlight from "@astrojs/starlight";
import starlightOpenAPI, { openAPISidebarGroups } from "starlight-openapi";

// Reads docs/user/ and docs/dev.md + docs/dev/*.md via scripts/sync-
// content.mjs (run before every dev/build - Starlight's own docsLoader()
// only reads this project's own src/content/docs/, so that script is the
// bridge, not a duplication of content) and docs/api/openapi.json
// (generated by backend's own `bun run gen:api-docs`, never hand-written)
// via starlight-openapi. The install guide, the update page, and the
// privacy page are the three pages release notes link (org standard).
export default defineConfig({
  integrations: [
    starlight({
      title: "MaiPai Home",
      description: "Docs for MaiPai Home, the private, self-hosted family AI hub.",
      social: [{ icon: "github", label: "GitHub", href: "https://github.com/getmaipai/home" }],
      plugins: [
        starlightOpenAPI([
          {
            base: "api",
            schema: "../api/openapi.json",
            label: "API reference",
          },
        ]),
      ],
      sidebar: [
        {
          label: "Guide",
          items: [{ autogenerate: { directory: "guide" } }],
        },
        {
          label: "Developer",
          items: [{ autogenerate: { directory: "dev" } }],
        },
        ...openAPISidebarGroups,
      ],
    }),
  ],
});
